// Converts one Google Maps Platform Discovery document into an OpenAPI 3.0 document.
// Usage: node discovery-to-openapi.mjs <discovery.json> > <name>-openapi.json
// Fetch the input from https://<service>.googleapis.com/$discovery/rest?version=<version>.
// Every operation takes the Maps Platform API key as the `key` query parameter.
import { readFileSync } from "node:fs";

const d = JSON.parse(readFileSync(process.argv[2], "utf8"));

const schema = (s) => {
  if (!s) return {};
  if (s.$ref) return { $ref: `#/components/schemas/${s.$ref}` };
  const out = {};
  if (s.description) out.description = s.description;
  if (s.type === "any") return out;
  if (s.type) out.type = s.type;
  if (s.format) out.format = s.format;
  if (s.enum) out.enum = s.enum;
  if (s.properties) out.properties = Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, schema(v)]));
  if (s.additionalProperties) out.additionalProperties = schema(s.additionalProperties);
  if (s.items) out.items = schema(s.items);
  if (s.type === "object" && !s.properties && !s.additionalProperties) out.additionalProperties = true;
  return out;
};

const param = (name, p, where = p.location) => {
  const base = schema({ type: p.type, format: p.format, enum: p.enum });
  return {
    name,
    in: where,
    required: where === "path" ? true : Boolean(p.required),
    description: p.description,
    schema: p.repeated ? { type: "array", items: base } : base,
  };
};

const paths = {};
const walk = (resources) => {
  for (const r of Object.values(resources ?? {})) {
    for (const m of Object.values(r.methods ?? {})) {
      // "{+name}" spans slashes ("places/ChIJ..."); the flatPath spells the segments out, so use it and
      // turn every segment into its own path parameter.
      const reserved = m.path.includes("{+");
      const template = reserved && m.flatPath ? m.flatPath : m.path;
      const key = `/${template.replace(/^\//, "").replace(/\{\+(\w+)\}/g, "{$1}")}`;
      const params = [];
      if (reserved && m.flatPath) {
        const original = m.path.match(/\{\+(\w+)\}/)?.[1];
        for (const [, name] of m.flatPath.matchAll(/\{(\w+)\}/g)) {
          params.push({
            name,
            in: "path",
            required: true,
            description: `Segment ${name} of the resource name${original ? ` (${m.parameters?.[original]?.description ?? original})` : ""}.`,
            schema: { type: "string" },
          });
        }
      }
      const skip = new Set(reserved && m.flatPath ? [m.path.match(/\{\+(\w+)\}/)?.[1]] : []);
      for (const [n, p] of Object.entries(m.parameters ?? {})) if (!skip.has(n)) params.push(param(n, p));
      const op = {
        operationId: m.id,
        description: m.description?.trim(),
        parameters: params,
        responses: {
          200: m.response
            ? { description: "Success", content: { "application/json": { schema: schema(m.response) } } }
            : { description: "Success" },
        },
        security: [{ apiKey: [] }],
      };
      if (m.request) op.requestBody = { required: true, content: { "application/json": { schema: schema(m.request) } } };
      (paths[key] ??= {})[m.httpMethod.toLowerCase()] = op;
    }
    walk(r.resources);
  }
};
// Methods can also sit directly on the root (Address Validation has `v1.validateAddress`).
walk(d.resources);
if (d.methods) walk({ root: { methods: d.methods } });

const doc = {
  openapi: "3.0.3",
  info: { title: d.title ?? d.name, version: `${d.version} (discovery revision ${d.revision})`, description: d.description },
  servers: [{ url: (d.rootUrl ?? d.baseUrl).replace(/\/$/, "") }],
  security: [{ apiKey: [] }],
  paths,
  components: {
    schemas: Object.fromEntries(Object.entries(d.schemas ?? {}).map(([k, v]) => [k, schema(v)])),
    securitySchemes: { apiKey: { type: "apiKey", in: "query", name: "key" } },
  },
};
process.stdout.write(JSON.stringify(doc) + "\n");

import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from the vendor's logo.
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml"
  }
];

import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  object,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter, type OpenapiToolNamesOptions } from "apps/openapi";
import { icons } from "./icon.js";
import {
  addressValidationOptions,
  airQualityOptions,
  geocodingOptions,
  geolocationOptions,
  placesOptions,
  pollenOptions,
  roadsOptions,
  routesOptions,
  solarOptions,
  weatherOptions,
} from "./openapi.js";

const googleMaps = defineProvider({
  name: "Google Maps",
  hosts: [
    "maps.googleapis.com",
    "places.googleapis.com",
    "routes.googleapis.com",
    "addressvalidation.googleapis.com",
    "solar.googleapis.com",
    "airquality.googleapis.com",
    "pollen.googleapis.com",
    "weather.googleapis.com",
    "roads.googleapis.com",
    "www.googleapis.com",
  ],
  auth: {
    apiKey: secrets({
      label: "Maps Platform API key",
      fields: object({ apiKey: string({ minLength: 1 }) }),
    }),
  },
  // Maps web services answer HTTP 200 with a status field, so a bad key must be read from the body. The check uses
  // the Geocoding API, which therefore has to be enabled for the key.
  async health({ account, fetch, signal }) {
    const url = new URL("https://maps.googleapis.com/maps/api/geocode/json");
    url.searchParams.set("address", "Mountain View");
    url.searchParams.set("key", account.fields.apiKey);
    const response = await fetch(url.toString(), { signal });
    const body = await decodeJson(response, object({ status: string() }));
    if (body.status !== "OK" && body.status !== "ZERO_RESULTS") {
      throw new Error(`Google Maps rejected the API key (${body.status}). Enable the Geocoding API for it.`);
    }
  },
});

export default defineApp(
  { user: { accounts: { googleMaps: googleMaps.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        user?.accounts.googleMaps ?? [],
        (account) => {
          const mount = (options: OpenapiToolNamesOptions) =>
            withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
              tool.kind === "mutation" ? always() : undefined,
            );
          return router(
            {
              places: mount(placesOptions),
              geocoding: mount(geocodingOptions),
              routes: mount(routesOptions),
              addressValidation: mount(addressValidationOptions),
              weather: mount(weatherOptions),
              airQuality: mount(airQualityOptions),
              pollen: mount(pollenOptions),
              solar: mount(solarOptions),
              roads: mount(roadsOptions),
              geolocation: mount(geolocationOptions),
            },
            { title: "Google Maps", description: "Google Maps Platform account." },
          );
        },
        { signal },
      ),
      {
        title: "Google Maps",
        description:
          "Google Maps Platform. places: text, nearby and autocomplete search, place details and photos. geocoding: geocode, reverse geocode, elevation, time zone. routes: routes and route matrices. addressValidation: validate postal addresses. weather, airQuality, pollen: conditions and forecasts. solar: rooftop solar potential. roads: snap to roads, nearest roads, speed limits. geolocation: locate a device.",
        icons,
      },
    ),
  }),
);

import type { JsonObject } from "apps";

// Hand-written OpenAPI documents for the Maps Platform web services Google does not publish a machine-readable
// description for: Geocoding, Elevation and Time Zone (maps.googleapis.com), Routes (routes.googleapis.com) and
// Geolocation (www.googleapis.com). Facts come from https://developers.google.com/maps/documentation.
const key = { apiKey: [] as string[] };
const securitySchemes = { apiKey: { type: "apiKey", in: "query", name: "key" } };
const result = { type: "object", additionalProperties: true };
const json = (schema: JsonObject = result) => ({ description: "Success", content: { "application/json": { schema } } });
const q = (name: string, description: string, required = false) => ({
  name,
  in: "query",
  required,
  description,
  schema: { type: "string" },
});
const fieldMask = {
  name: "X-Goog-FieldMask",
  in: "header",
  required: true,
  description:
    "Comma-separated response fields to return, for example `routes.duration,routes.distanceMeters,routes.polyline.encodedPolyline`. Use `*` for all fields (development only).",
  schema: { type: "string" },
};
const body = (description: string, properties: JsonObject, required: string[] = []) => ({
  required: true,
  content: { "application/json": { schema: { type: "object", description, properties, required, additionalProperties: true } } },
});
const object = (description: string) => ({ type: "object", description, additionalProperties: true });
const text = (description: string) => ({ type: "string", description });
const list = (description: string) => ({ type: "array", description, items: { type: "object", additionalProperties: true } });

const waypoint = (what: string) =>
  object(
    `${what} as a Waypoint: one of \`location\` ({ latLng: { latitude, longitude }, heading? }), \`placeId\` or \`address\`, plus optional \`via\`, \`vehicleStopover\` and \`sideOfRoad\`.`,
  );

const routeModifiers = object(
  "RouteModifiers: avoidTolls, avoidHighways, avoidFerries, avoidIndoor, vehicleInfo, tollPasses.",
);

export const geocodingDocument: JsonObject = {
  openapi: "3.0.3",
  info: {
    title: "Google Maps Geocoding, Elevation and Time Zone APIs",
    version: "v3",
    description: "Address and coordinate lookup, elevation and time zones. Responses carry a `status` field; errors still use HTTP 200.",
  },
  servers: [{ url: "https://maps.googleapis.com" }],
  security: [key],
  paths: {
    "/maps/api/geocode/json": {
      get: {
        operationId: "geocode",
        description:
          "Geocodes an address, component filter or Place ID to coordinates, or reverse geocodes `latlng` (or a Place ID) to addresses. Provide at least one of `address`, `components`, `latlng` or `place_id`.",
        parameters: [
          q("address", "Street address or plus code to geocode, for example `1600 Amphitheatre Parkway, Mountain View, CA`."),
          q("latlng", "Latitude and longitude to reverse geocode, comma separated, for example `40.714224,-73.961452`."),
          q("place_id", "Place ID to return the address for."),
          q("components", "Pipe-separated component filters, for example `country:ES|postal_code:08001`."),
          q("bounds", "Bounding box to bias results, `south_west_lat,south_west_lng|north_east_lat,north_east_lng`."),
          q("region", "Region bias as a two-character ccTLD code, for example `uk`."),
          q("language", "Language for returned addresses, for example `en`."),
          q("result_type", "Pipe-separated address types to filter reverse geocoding results by."),
          q("location_type", "Pipe-separated location types to filter reverse geocoding results by: ROOFTOP, RANGE_INTERPOLATED, GEOMETRIC_CENTER, APPROXIMATE."),
        ],
        responses: { 200: json() },
        security: [key],
      },
    },
    "/maps/api/elevation/json": {
      get: {
        operationId: "elevation",
        description: "Returns the elevation in meters for locations, or sampled along a path. Provide `locations`, or `path` with `samples`.",
        parameters: [
          q("locations", "Pipe-separated `lat,lng` pairs, or `enc:` followed by an encoded polyline."),
          q("path", "Pipe-separated `lat,lng` pairs, or `enc:` followed by an encoded polyline, to sample along."),
          q("samples", "Number of evenly spaced samples along `path`."),
        ],
        responses: { 200: json() },
        security: [key],
      },
    },
    "/maps/api/timezone/json": {
      get: {
        operationId: "timezone",
        description: "Returns the time zone id, name, UTC offset and daylight saving offset for a location at a moment in time.",
        parameters: [
          q("location", "`lat,lng` of the point.", true),
          q("timestamp", "Seconds since midnight UTC, January 1, 1970; selects the daylight saving rules in effect.", true),
          q("language", "Language for the time zone name, for example `en`."),
        ],
        responses: { 200: json() },
        security: [key],
      },
    },
  },
  components: { securitySchemes },
};

export const routesDocument: JsonObject = {
  openapi: "3.0.3",
  info: {
    title: "Google Maps Routes API",
    version: "v2",
    description: "Routes between places, and route matrices, with traffic-aware durations.",
  },
  servers: [{ url: "https://routes.googleapis.com" }],
  security: [key],
  paths: {
    "/directions/v2:computeRoutes": {
      post: {
        operationId: "computeRoutes",
        description:
          "Returns a primary route, and optionally alternatives, between an origin and destination with optional intermediates. `X-Goog-FieldMask` is required.",
        parameters: [fieldMask],
        requestBody: body(
          "ComputeRoutesRequest",
          {
            origin: waypoint("The start"),
            destination: waypoint("The end"),
            intermediates: list("Waypoints to pass through or stop at, in order."),
            travelMode: text("DRIVE, BICYCLE, WALK, TWO_WHEELER or TRANSIT."),
            routingPreference: text("TRAFFIC_UNAWARE, TRAFFIC_AWARE or TRAFFIC_AWARE_OPTIMAL (DRIVE and TWO_WHEELER only)."),
            polylineQuality: text("OVERVIEW or HIGH_QUALITY."),
            polylineEncoding: text("ENCODED_POLYLINE or GEO_JSON_LINESTRING."),
            departureTime: text("RFC 3339 timestamp, for example 2026-10-12T09:00:00Z."),
            arrivalTime: text("RFC 3339 timestamp; TRANSIT only."),
            computeAlternativeRoutes: { type: "boolean", description: "Also return alternative routes." },
            routeModifiers,
            languageCode: text("BCP-47 language code, for example en-US."),
            regionCode: text("Two-letter ccTLD region code."),
            units: text("METRIC or IMPERIAL."),
            optimizeWaypointOrder: { type: "boolean", description: "Reorder intermediates for the shortest route." },
            requestedReferenceRoutes: list("Reference routes to compute, for example FUEL_EFFICIENT."),
            extraComputations: list("Extra computations, for example TOLLS, FUEL_CONSUMPTION, TRAFFIC_ON_POLYLINE."),
            transitPreferences: object("TransitPreferences: allowedTravelModes, routingPreference."),
          },
          ["origin", "destination"],
        ),
        responses: { 200: json() },
        security: [key],
      },
    },
    "/distanceMatrix/v2:computeRouteMatrix": {
      post: {
        operationId: "computeRouteMatrix",
        description:
          "Returns distance and duration for every origin and destination pair (at most 625 elements). The response is an array of elements, one per pair. `X-Goog-FieldMask` is required, for example `originIndex,destinationIndex,duration,distanceMeters,status,condition`.",
        parameters: [fieldMask],
        requestBody: body(
          "ComputeRouteMatrixRequest",
          {
            origins: list("RouteMatrixOrigin items: { waypoint, routeModifiers }."),
            destinations: list("RouteMatrixDestination items: { waypoint }."),
            travelMode: text("DRIVE, BICYCLE, WALK, TWO_WHEELER or TRANSIT."),
            routingPreference: text("TRAFFIC_UNAWARE, TRAFFIC_AWARE or TRAFFIC_AWARE_OPTIMAL."),
            departureTime: text("RFC 3339 timestamp."),
            arrivalTime: text("RFC 3339 timestamp; TRANSIT only."),
            languageCode: text("BCP-47 language code."),
            regionCode: text("Two-letter ccTLD region code."),
            units: text("METRIC or IMPERIAL."),
            extraComputations: list("Extra computations, for example TOLLS."),
            trafficModel: text("BEST_GUESS, PESSIMISTIC or OPTIMISTIC."),
            transitPreferences: object("TransitPreferences: allowedTravelModes, routingPreference."),
          },
          ["origins", "destinations"],
        ),
        responses: { 200: { description: "Success", content: { "application/json": { schema: { type: "array", items: result } } } } },
        security: [key],
      },
    },
  },
  components: { securitySchemes },
};

export const geolocationDocument: JsonObject = {
  openapi: "3.0.3",
  info: {
    title: "Google Maps Geolocation API",
    version: "v1",
    description: "Locates a device from the cell towers and Wi-Fi access points it can see.",
  },
  servers: [{ url: "https://www.googleapis.com" }],
  security: [key],
  paths: {
    "/geolocation/v1/geolocate": {
      post: {
        operationId: "geolocate",
        description: "Returns an estimated location and accuracy radius from cell tower and Wi-Fi access point data. With no data it falls back to the caller's IP address when `considerIp` is true.",
        requestBody: body("GeolocationRequest", {
          homeMobileCountryCode: { type: "integer", description: "Home mobile country code of the device's carrier." },
          homeMobileNetworkCode: { type: "integer", description: "Home mobile network code of the device's carrier." },
          radioType: text("lte, gsm, cdma or wcdma."),
          carrier: text("Carrier name."),
          considerIp: { type: "boolean", description: "Fall back to IP geolocation when no tower or Wi-Fi data is given. Defaults to true." },
          cellTowers: list("Cell towers: { cellId, locationAreaCode, mobileCountryCode, mobileNetworkCode, ... }."),
          wifiAccessPoints: list("Wi-Fi access points, at least two: { macAddress, signalStrength, channel, ... }."),
        }),
        responses: { 200: json() },
        security: [key],
      },
    },
  },
  components: { securitySchemes },
};

// Google Maps Platform is one product served from several hosts, so each API is its own document mounted under its
// own key in index.ts. places, addressvalidation, solar, airquality, pollen, weather and roads are generated from
// Google's official Discovery documents by discovery-to-openapi.mjs (revision 20261006 to 20261007); geocoding,
// routes and geolocation are hand-written in legacy.ts because Google publishes no machine-readable description.
// Credentials are the Maps Platform API key, sent as the `key` query parameter.
import type { JsonObject } from "apps";
import type { OpenapiToolNamesOptions } from "apps/openapi";
import addressvalidation from "./addressvalidation-openapi.json" with { type: "json" };
import airquality from "./airquality-openapi.json" with { type: "json" };
import places from "./places-openapi.json" with { type: "json" };
import pollen from "./pollen-openapi.json" with { type: "json" };
import roads from "./roads-openapi.json" with { type: "json" };
import solar from "./solar-openapi.json" with { type: "json" };
import weather from "./weather-openapi.json" with { type: "json" };
import { geocodingDocument, geolocationDocument, routesDocument } from "./legacy.ts";

// The inferred JSON type has no index signature, so widen it once here.
const widen = (value: unknown): JsonObject => JSON.parse(JSON.stringify(value));

const shared = {
  securitySchemes: { apiKey: { type: "apiKey", in: "query", name: "key" } },
  methods: { apiKey: [{ scheme: "apiKey", field: "apiKey", part: "value", prefix: "" }] },
  oauth: [],
} as const;

const api = <const K extends Record<string, "query">>(
  document: unknown,
  origin: string,
  kinds: K,
  patches?: NonNullable<OpenapiToolNamesOptions["patches"]>,
) =>
  ({ ...shared, source: { document: widen(document) }, allowedOrigin: origin, kinds, ...(patches ? { patches } : {}) }) satisfies OpenapiToolNamesOptions;

// Places (New) rejects searchText, searchNearby and places.get without a field mask (X-Goog-FieldMask header), and the
// Discovery document drops the global `fields` parameter, so add the header as a required parameter. Autocomplete does
// not need it. Arrays are valid patch values at runtime; the declared type only admits objects.
const placesPatches = [
  { op: "replace", path: "/paths/~1v1~1places:searchText/post/parameters", value: [{"name": "X-Goog-FieldMask", "in": "header", "required": true, "description": "Required. Comma-separated response fields to return, for example `places.displayName,places.formattedAddress,places.id` (use `*` to return everything, which is billed at the highest tier). The request fails without it.", "schema": {"type": "string"}}] },
  { op: "replace", path: "/paths/~1v1~1places:searchNearby/post/parameters", value: [{"name": "X-Goog-FieldMask", "in": "header", "required": true, "description": "Required. Comma-separated response fields to return, for example `places.displayName,places.formattedAddress,places.id` (use `*` to return everything, which is billed at the highest tier). The request fails without it.", "schema": {"type": "string"}}] },
  { op: "replace", path: "/paths/~1v1~1places~1{placesId}/get/parameters", value: [{"name": "placesId", "in": "path", "required": true, "description": "Segment placesId of the resource name (Required. The resource name of a place, in the `places/{place_id}` format.).", "schema": {"type": "string"}}, {"name": "languageCode", "in": "query", "required": false, "description": "Optional. Place details will be displayed with the preferred language if available. Current list of supported languages: https://developers.google.com/maps/faq#languagesupport.", "schema": {"type": "string"}}, {"name": "regionCode", "in": "query", "required": false, "description": "Optional. The Unicode country/region code (CLDR) of the location where the request is coming from. This parameter is used to display the place details, like region-specific place name, if available. The parameter can affect results based on applicable law. For more information, see https://www.unicode.org/cldr/charts/latest/supplemental/territory_language_information.html. Note that 3-digit region codes are not currently supported.", "schema": {"type": "string"}}, {"name": "sessionToken", "in": "query", "required": false, "description": "Optional. A string which identifies an Autocomplete session for billing purposes. Must be a URL and filename safe base64 string with at most 36 ASCII characters in length. Otherwise an INVALID_ARGUMENT error is returned. The session begins when the user starts typing a query, and concludes when they select a place and a call to Place Details or Address Validation is made. Each session can have multiple queries, followed by one Place Details or Address Validation request. The credentials used for each request within a session must belong to the same Google Cloud Console project. Once a session has concluded, the token is no longer valid; your app must generate a fresh token for each session. If the `session_token` parameter is omitted, or if you reuse a session token, the session is charged as if no session token was provided (each request is billed separately). We recommend the following guidelines: * Use session tokens for all Place Autocomplete calls. * Generate a fresh token for each session. Using a version 4 UUID is recommended. * Ensure that the credentials used for all Place Autocomplete, Place Details, and Address Validation requests within a session belong to the same Cloud Console project. * Be sure to pass a unique session token for each new session. Using the same token for more than one session will result in each request being billed individually.", "schema": {"type": "string"}}, {"name": "X-Goog-FieldMask", "in": "header", "required": true, "description": "Required. Comma-separated response fields to return, for example `places.displayName,places.formattedAddress,places.id` (use `*` to return everything, which is billed at the highest tier). The request fails without it.", "schema": {"type": "string"}}] },
] as unknown as NonNullable<OpenapiToolNamesOptions["patches"]>;

// POST operations that only read are queries, so they run without an approval prompt.
export const placesOptions = api(places, "https://places.googleapis.com", {
  "places.places.searchText": "query",
  "places.places.searchNearby": "query",
  "places.places.autocomplete": "query",
}, placesPatches);
export const addressValidationOptions = api(addressvalidation, "https://addressvalidation.googleapis.com", {
  "addressvalidation.validateAddress": "query",
});
export const solarOptions = api(solar, "https://solar.googleapis.com", {});
export const airQualityOptions = api(airquality, "https://airquality.googleapis.com", {
  "airquality.currentConditions.lookup": "query",
  "airquality.forecast.lookup": "query",
  "airquality.history.lookup": "query",
});
export const pollenOptions = api(pollen, "https://pollen.googleapis.com", {});
export const weatherOptions = api(weather, "https://weather.googleapis.com", {});
export const roadsOptions = api(roads, "https://roads.googleapis.com", {});
export const geocodingOptions = api(geocodingDocument, "https://maps.googleapis.com", {});
export const routesOptions = api(routesDocument, "https://routes.googleapis.com", {
  computeRoutes: "query",
  computeRouteMatrix: "query",
});
export const geolocationOptions = api(geolocationDocument, "https://www.googleapis.com", { geolocate: "query" });

// scripts/tools.ts counts this one; the others are counted by the README check.
export const options = placesOptions;

{
  "name": "@executor.sh/google-maps",
  "description": "Search places, geocode addresses, compute routes, and look up weather, air quality, pollen, solar, elevation and time zones with Google Maps Platform.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Google Maps"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.13"
  }
}
